import java.util.*;

public class Main {

    record Span(String trace, String id, String parent, String service,
                String minute, long durationMs, String status) {
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int threshold = sc.nextInt();
        int m = sc.nextInt();
        String breach = null;
        for (int i = 0; i < m; i++) {
            String minute = sc.next();
            int errors = sc.nextInt();
            if (breach == null && errors > threshold) {
                breach = minute;
            }
        }
        int s = sc.nextInt();
        List<Span> spans = new ArrayList<>();
        for (int i = 0; i < s; i++) {
            spans.add(new Span(sc.next(), sc.next(), sc.next(), sc.next(),
                    sc.next(), sc.nextLong(), sc.next()));
        }
        int l = sc.nextInt();
        List<String[]> logs = new ArrayList<>();
        for (int i = 0; i < l; i++) {
            String trace = sc.next();
            String span = sc.next();
            String level = sc.next();
            logs.add(new String[] {trace, span, level, sc.nextLine().trim()});
        }

        if (breach == null) {
            System.out.println("breach=NONE");
            return;
        }
        System.out.println("breach=" + breach);

        String target = null;
        for (Span span : spans) {
            if (span.minute().equals(breach) && span.status().equals("error")
                    && (target == null || span.trace().compareTo(target) < 0)) {
                target = span.trace();
            }
        }
        if (target == null) {
            System.out.println("trace=NONE");
            return;
        }
        System.out.println("trace=" + target);

        Map<String, Span> byId = new LinkedHashMap<>();
        for (Span span : spans) {
            if (span.trace().equals(target)) {
                byId.put(span.id(), span);
            }
        }

        Span deepest = null;
        int bestDepth = -1;
        for (Span span : byId.values()) {
            if (!span.status().equals("error")) {
                continue;
            }
            int depth = 0;
            for (Span cursor = span; !cursor.parent().equals("-");
                    cursor = byId.get(cursor.parent())) {
                depth++;
            }
            if (depth > bestDepth
                    || (depth == bestDepth && span.id().compareTo(deepest.id()) < 0)) {
                bestDepth = depth;
                deepest = span;
            }
        }

        Deque<String> path = new ArrayDeque<>();
        for (Span cursor = deepest; ; cursor = byId.get(cursor.parent())) {
            path.addFirst(cursor.service());
            if (cursor.parent().equals("-")) {
                break;
            }
        }
        System.out.println("path=" + String.join(">", path));

        List<String> lines = new ArrayList<>();
        for (String[] log : logs) {
            if (log[0].equals(target) && log[1].equals(deepest.id())) {
                lines.add("log=" + log[2] + " " + log[3]);
            }
        }
        if (lines.isEmpty()) {
            System.out.println("log=NONE");
        } else {
            lines.forEach(System.out::println);
        }
    }
}

