import java.util.*;

public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int capacity = sc.nextInt(), threshold = sc.nextInt(), n = sc.nextInt();
        int queued = 0, consecutive = 0, ok = 0, fail = 0, rejected = 0, full = 0;
        boolean open = false;
        for (int i = 0; i < n; i++) {
            String id = sc.next(), outcome = sc.next();
            if (open) {
                System.out.println("rejected " + id);
                rejected++;
                continue;
            }
            if (queued == capacity) {
                System.out.println("full " + id);
                full++;
                continue;
            }
            queued++;
            if (outcome.equals("ok")) {
                consecutive = 0;
                ok++;
                System.out.println("ok " + id);
            } else {
                consecutive++;
                fail++;
                System.out.println("fail " + id);
                if (consecutive >= threshold) open = true;
            }
        }
        System.out.println("state=" + (open ? "OPEN" : "CLOSED"));
        System.out.println("queued=" + queued + "/" + capacity);
        System.out.println("ok=" + ok + " fail=" + fail + " rejected=" + rejected + " full=" + full);
        int handled = ok + fail;
        System.out.println(handled == 0 ? "success=NO_DATA" : String.format(Locale.ROOT, "success=%.2f%%", ok * 100.0 / handled));
    }
}

